/**
 * Jev (TypeSafe AI) — a "System 1" typed-decision model, used as a cheaper,
 * faster alternative to OpenAI for relevance scoring.
 *
 * Unlike a chat model, Jev does not write prose: a request poses one or more
 * typed questions (a numeric "score" on a declared scale, or a "choice" from
 * a fixed set of keys) and gets back a calibrated value for each, in one
 * round trip. That fits scoring well — it is exactly "pick a number" and
 * "pick a product" — but it means the reasoning/summary text here is
 * assembled from the returned signals and the evidence, not generated by the
 * model, the same way the free heuristic provider builds its own.
 *
 * Needs its own account: an API key from https://console.typesafe.ai/, set as
 * JEV_API_KEY. This integration is written against TypeSafe's publicly
 * documented request/response shape as of Sept 2026 — verify the field names
 * in `JevResponse` against a real response the first time this runs, since a
 * fast-moving API's exact schema is the one thing worth re-checking live.
 */
import { env } from '../../config/env.js';
import type { QualificationSignals } from '../../types/domain.js';
import type { AiProvider, EnrichmentInput, EnrichmentResult } from './types.js';
import { confirmedInstruments } from '../discovery/instrumentDetector.js';

const API_URL = 'https://api.typesafe.ai/v1/systemone';
/** USD per 1M input tokens (Sept 2026 pricing); output tokens are free. For the run budget guard, not billing. */
const INPUT_PRICE_PER_1M = 0.042;

/** An 11-point scale so a returned index (0-10) maps onto 0-100 in steps of 10. */
const SCALE_11 = Array.from({ length: 11 }, (_, i) => String(i * 10));

interface JevAnswer {
  score?: number;
  choice?: string;
  noul?: number;
}
interface JevResponse {
  model?: string;
  answers: Record<string, JevAnswer>;
  usage?: { input_tokens?: number; output_tokens?: number };
}

/** A run's keyword override, stated to the model as what this run cares about. */
function focusLine(focus?: EnrichmentInput['focus']): string {
  if (!focus) return '';
  const parts = [
    focus.keywords.length ? `Focus keywords for this run${focus.keywordsOnly ? ' (judge relevance on these only)' : ''}: ${focus.keywords.join(', ')}` : '',
    focus.areas.length ? `Focus application areas: ${focus.areas.join('; ')}` : '',
  ].filter(Boolean);
  return parts.join('\n');
}

export class JevProvider implements AiProvider {
  readonly name: string;
  readonly billable = true;
  private readonly apiKey: string;

  constructor(apiKey: string, model = env.JEV_MODEL) {
    this.apiKey = apiKey;
    this.name = model;
  }

  async enrich({ candidate, catalog, focus }: EnrichmentInput): Promise<EnrichmentResult> {
    // Sightings that still need review (a bare brand in a non-electrochemistry paper) do not count.
    const instruments = confirmedInstruments(candidate.instruments);
    const ownsInstrument = instruments.length > 0;

    const state = [
      `Researcher: ${candidate.name}`,
      candidate.title ? `Position: ${candidate.title}` : '',
      candidate.institutionName ? `Institution: ${candidate.institutionName}` : '',
      candidate.topics.length ? `Indexed topics: ${candidate.topics.join(', ')}` : '',
      candidate.publications.length
        ? `Recent publications: ${candidate.publications.map((p) => p.title).join('; ')}`
        : '',
      ownsInstrument
        ? `Instruments in use: ${instruments.map((i) => `${i.model ?? i.brand} (${i.vendor === 'classone' ? 'Class One brand' : 'competitor'})`).join(', ')}`
        : '',
      `Evidence: ${candidate.evidenceText.slice(0, 1500)}`,
      focusLine(focus),
    ]
      .filter(Boolean)
      .join('\n');

    const activeCatalog = catalog.filter((p) => p.isActive);
    const productCriteria: Record<string, string> = { none: 'no catalog product fits well' };
    for (const p of activeCatalog) productCriteria[p.productId] = `${p.name} — for ${p.applicationAreas.join(', ')}`;

    const body = {
      model: this.name,
      state,
      questions: {
        product_relevance: {
          type: 'score',
          instructions:
            'How strongly does this researcher\'s work require electrochemical instrumentation (potentiostats, galvanostats, EIS, voltammetry, electrocatalysis, battery/corrosion/biosensor characterisation)? Be strict — an adjacent field that merely mentions "electrode" or "catalysis" is a weak match, not a strong one.',
          criteria: SCALE_11,
        },
        institutional_strength: {
          type: 'score',
          instructions: 'Research capacity and funding level of the institution, inferred from the evidence given.',
          criteria: SCALE_11,
        },
        recency: {
          type: 'score',
          instructions: 'How current is the evidence — recent publications and activity score higher than old or absent dates.',
          criteria: SCALE_11,
        },
        engagement_potential: {
          type: 'score',
          instructions: 'How reachable and likely to respond is this person, based on the contact and profile signals available.',
          criteria: SCALE_11,
        },
        best_product: {
          type: 'choice',
          instructions: 'Which single catalog product, if any, best fits this researcher\'s work? Pick "none" if nothing fits well — never guess.',
          criteria: productCriteria,
        },
      },
    };

    const response = await fetch(API_URL, {
      method: 'POST',
      headers: { Authorization: `Bearer ${this.apiKey}`, 'Content-Type': 'application/json' },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(20_000),
    });
    if (!response.ok) {
      throw new Error(`Jev ${response.status} ${response.statusText}`);
    }
    const data = (await response.json()) as JevResponse;
    if (!data.answers) throw new Error('Jev returned no answers — check the response shape against JevResponse');

    // The documented "score" type returns a position on the declared scale
    // (0-10 for an 11-point scale here); a value already in 0-100 passes
    // through unchanged, in case the live API returns the scale value itself
    // rather than its index.
    const scaleToScore = (v: number | undefined): number => {
      if (v === undefined || !Number.isFinite(v)) return 0;
      const scaled = v <= 10 ? v * 10 : v;
      return Math.max(0, Math.min(100, Math.round(scaled)));
    };

    const productRelevance = scaleToScore(data.answers.product_relevance?.score);
    const institutionalStrength = scaleToScore(data.answers.institutional_strength?.score);
    const recency = scaleToScore(data.answers.recency?.score);
    const engagementPotential = scaleToScore(data.answers.engagement_potential?.score);

    const bestProduct = data.answers.best_product?.choice;
    const recommendedProductIds =
      bestProduct && bestProduct !== 'none' && activeCatalog.some((p) => p.productId === bestProduct) ? [bestProduct] : [];

    // Same weighting the rule-based scorer uses: product fit dominates
    // deliberately, since a well-funded, reachable researcher who does not do
    // electrochemistry is still not a lead.
    const relevanceScore = Math.round(
      productRelevance * 0.55 + recency * 0.15 + institutionalStrength * 0.15 + engagementPotential * 0.15,
    );

    const signals: QualificationSignals = { productRelevance, institutionalStrength, recency, engagementPotential };

    const instrumentNote = ownsInstrument
      ? ` Uses ${[...new Set(instruments.map((i) => i.model ?? i.brand))].slice(0, 4).join(', ')}` +
        (instruments.some((i) => i.vendor === 'classone') ? ' (existing Class One brand user).' : ' (competitor equipment — proven buyer).')
      : '';

    const sentences = candidate.evidenceText
      .split(/(?<=[.!?])\s+/)
      .filter((s) => s.trim().length > 20)
      .slice(0, 2)
      .join(' ');

    const usage = data.usage;
    const costUsd = ((usage?.input_tokens ?? 0) / 1_000_000) * INPUT_PRICE_PER_1M;

    return {
      relevanceScore,
      relevanceReasoning: `Jev (System 1) scores — product fit ${productRelevance}, institution ${institutionalStrength}, recency ${recency}, engagement ${engagementPotential}.${instrumentNote}`,
      signals,
      summary:
        [candidate.institutionName ? `${candidate.name} (${candidate.institutionName}).` : `${candidate.name}.`, sentences]
          .filter(Boolean)
          .join(' ')
          .slice(0, 900) || candidate.name,
      topics: candidate.topics.slice(0, 8),
      recommendedProductIds,
      recommendedProductNotes: recommendedProductIds.length > 0 ? 'Picked by Jev as the single best-fitting catalog product.' : undefined,
      model: data.model ?? this.name,
      costUsd,
    };
  }
}
